namespace A33.Instrument.Protocol;
public readonly record struct ModbusException(byte Function,byte Code);
public static class ModbusResponseCodec { public static ushort[] ReadHolding(ReadOnlySpan<byte> pdu){if(pdu.Length<3||pdu[0]!=3||pdu[1]!=pdu.Length-2||((pdu[1]&1)!=0))throw new FormatException("invalid FC03 response");var r=new ushort[pdu[1]/2];for(var i=0;i<r.Length;i++)r[i]=(ushort)(pdu[2+2*i]<<8|pdu[3+2*i]);return r;} public static void ValidateWriteSingle(ReadOnlySpan<byte> pdu){if(pdu.Length!=6||pdu[0]!=6)throw new FormatException("invalid FC06 response");} public static ushort ValidateWriteMultiple(ReadOnlySpan<byte> pdu){if(pdu.Length!=6||pdu[0]!=16)throw new FormatException("invalid FC16 response");return (ushort)(pdu[4]<<8|pdu[5]);} public static ModbusException? Exception(ReadOnlySpan<byte> pdu){return pdu.Length>=2&&(pdu[0]&0x80)!=0?new ModbusException((byte)(pdu[0]&0x7f),pdu[1]):null;} }
